// Ejemplo de uso del Modal mejorado
import React, { useState } from 'react';
import Modal from './Modal';

function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);

  const toggleModal = () => {
    setIsModalOpen(!isModalOpen);
  };

  const handleModalError = (errorMessage, errorObject) => {
    console.error('Error en modal:', errorMessage);
    // Aquí podrías enviar el error a un servicio de logging
    // o mostrar una notificación al usuario
  };

  return (
    <div className="App">
      <h1>Aplicación con Modal Mejorado</h1>

      <button 
        onClick={toggleModal}
        className="btn btn-primary"
      >
        Abrir Modal de Contacto
      </button>

      {/* Uso básico */}
      <Modal 
        isOpen={isModalOpen}
        toggleModal={toggleModal}
      />

      {/* Uso avanzado con props personalizadas */}
      <Modal 
        isOpen={isModalOpen}
        toggleModal={toggleModal}
        title="¡Contáctanos!"
        message="Estamos listos para ayudarte. Haz clic en el botón para iniciar una conversación por WhatsApp."
        buttonText="Chatear ahora"
        loadingText="Preparando chat..."
        onError={handleModalError}
        whatsappUrl="https://api.whatsapp.com/send/?phone=51995092832&text=Hola,%20necesito%20información"
      />
    </div>
  );
}

export default App;
